// Generated by make_effects.py; matching browser and hardware formulas.
#pragma once
#include <math.h>
inline float wrap(float x,float n){return fmodf(fmodf(x,n)+n,n);}
inline float smooth(float x){x=fmaxf(0,fminf(1,x));return x*x*x*(x*(x*6-15)+10);}
inline float pulse(float t,float c,float p,float w){return expf(-powf(wrap(t-c+p/2,p)-p/2,2)/(w*w));}
inline bool validEffect(const String& e){return e=="static"||e=="rev"||e=="chase"||e=="breathe"||e=="wave"||e=="scanner"||e=="ripple"||e=="heartbeat"||e=="ember"||e=="cascade";}
inline float effectLevel(const String& effect,float t,int i,int j,int n){const float TAU=6.28318530718f;const float x=float(j)/n;
if(effect=="static")return 1;
if(effect=="rev")return smooth(t*3+t*t*1.4-(i==0?3:0)-j);
if(effect=="chase")return 0.025+0.975*expf(-powf(wrap(x-t*0.32+0.5,1)-0.5,2)/0.018);
if(effect=="breathe")return 0.08+0.92*powf((1-cosf(t*1.8))/2,1.4);
if(effect=="wave")return 0.08+0.92*(1+sinf(t*2.2-x*TAU-i*0.5))/2;
if(effect=="scanner")return 0.025+0.975*expf(-powf(x-(1-cosf(t*1.7))/2,2)/0.028);
if(effect=="ripple")return 0.06+0.94*powf((1+cosf(fabsf(x-0.5)*TAU*1.6-t*2.4))/2,2);
if(effect=="heartbeat")return 0.06+0.94*fminf(1,pulse(t,0.48,2.8,0.15)+0.65*pulse(t,0.88,2.8,0.19));
if(effect=="ember")return 0.44+0.22*sinf(t*1.3+j*1.7+i*2.1)+0.13*sinf(t*2.73+j*0.8+i)+0.09*sinf(t*4.1-j*1.2);
if(effect=="cascade")return 0.08+0.92*powf((1+sinf(t*1.9-i*TAU/3-x*0.7))/2,1.6);
return 1;}
